{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest structural analogue sharing the methoxyquinoline and vinyl-piperidine core, has an absolute oral bioavailability of 80% in healthy subjects, directly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, a methoxyquinoline-containing drug, has an absolute bioavailability of about 85% in humans, supporting high oral bioavailability for the methoxyquinoline scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride, a methoxy-substituted heteroaromatic with a basic amine, shows oral systemic availability of about 89.7%, supporting high bioavailability for similarly ionizable methoxy-heteroaromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Midodrine, a methoxy-substituted aromatic drug, has an absolute bioavailability of 93%, providing additional support that methoxy-substituted aromatic amines can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tegaserod, a methoxyindole with a basic guanidine side chain, has an absolute bioavailability of only about 10%, representing a low-bioavailability counterexample, but its indole and guanidine structure is more distant from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Melatonin, a methoxyindole, has an absolute bioavailability of about 8.6% in males, but its small indole structure and extensive first-pass metabolism limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue viqualine has high human oral bioavailability (73-80%) and shares the methoxyquinoline and vinyl-piperidine core. Other methoxy-substituted heteroaromatic drugs with basic amines also show high F, while low-F examples are structurally more distant indoles with extensive first-pass metabolism. Thus the query is predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the exact query molecule.",
    "Morgan similarities to the closest analogue are modest (~0.41), limiting quantitative transfer.",
    "The metabolic stability and first-pass extraction of the constrained bicyclic amine and secondary alcohol are not directly known."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

